<?php require __DIR__.'/../config/bootstrap.php'; require_admin(); /* This check was missing: the POST handler below ran before includes/admin_header.php performed the login check, so anyone holding a CSRF token from the public contact form could add or delete records while signed out. */ $admin_title='Social Media'; $platforms=['Facebook'=>'fa-brands fa-facebook-f','Instagram'=>'fa-brands fa-instagram','LinkedIn'=>'fa-brands fa-linkedin-in','YouTube'=>'fa-brands fa-youtube','TikTok'=>'fa-brands fa-tiktok','X'=>'fa-brands fa-x-twitter','WhatsApp'=>'fa-brands fa-whatsapp','Telegram'=>'fa-brands fa-telegram','Pinterest'=>'fa-brands fa-pinterest-p','Other'=>'fa-solid fa-link']; if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$action=$_POST['action']??'';if($action==='save'){$id=(int)($_POST['id']??0);$platform=trim((string)($_POST['platform']??'Other'));$urlValue=trim((string)($_POST['url']??''));$icon=$platforms[$platform]??$platforms['Other'];if(!filter_var($urlValue,FILTER_VALIDATE_URL)||!preg_match('~^https?://~i',$urlValue))throw new UserMessageException('Enter the full profile address including https://, for example https://facebook.com/yourpage');$sort=(int)($_POST['sort_order']??0);$active=isset($_POST['active'])?1:0;if($id){db()->prepare('UPDATE social_links SET platform=?,url=?,icon_class=?,sort_order=?,active=? WHERE id=?')->execute([$platform,$urlValue,$icon,$sort,$active,$id]);}else{db()->prepare('INSERT INTO social_links(platform,url,icon_class,sort_order,active) VALUES(?,?,?,?,?)')->execute([$platform,$urlValue,$icon,$sort,$active]);}flash('success','Social profile saved.');}elseif($action==='delete'){db()->prepare('DELETE FROM social_links WHERE id=?')->execute([post_int('id')]);flash('success','Social profile removed.');}header('Location: '.url('admin/socials.php'));exit;}catch(Throwable $e){flash_exception($e);header('Location: '.url('admin/socials.php'));exit;}} $edit=null;if(isset($_GET['edit'])){$st=db()->prepare('SELECT * FROM social_links WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$items=db()->query('SELECT * FROM social_links ORDER BY sort_order,id')->fetchAll();require __DIR__.'/../includes/admin_header.php'; ?><div class="admin-card"><div class="admin-card-head"><div><h2><?=$edit?'Edit social profile':'Add social profile'?></h2><p>Accounts are stored in MySQL. The public footer creates the icon from the saved platform record; no account URLs are hard-coded.</p></div></div><form method="post" class="admin-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="form-cols"><div><label>Platform</label><select name="platform"><?php foreach($platforms as $name=>$icon):?><option value="<?=e($name)?>" <?=($edit['platform']??'Facebook')===$name?'selected':''?>><?=e($name)?></option><?php endforeach;?></select></div><div><label>Profile URL</label><input name="url" type="url" required placeholder="https://..." value="<?=e($edit['url']??'')?>"></div><div><label>Sort order</label><input type="number" name="sort_order" value="<?=e($edit['sort_order']??0)?>"></div><div><label>&nbsp;</label><label class="check"><input type="checkbox" name="active" <?=($edit===null||!empty($edit['active']))?'checked':''?>> Show in footer</label></div></div><button class="admin-button" type="submit">Save Social Profile</button><?php if($edit):?> <a class="small-button" href="<?=e(url('admin/socials.php'))?>">Cancel</a><?php endif;?></form></div><div class="admin-card"><div class="table-wrap"><table class="table"><thead><tr><th>Icon</th><th>Platform</th><th>URL</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($items as $x):?><tr><td><i class="<?=e($x['icon_class'])?>"></i></td><td><?=e($x['platform'])?></td><td><?=e($x['url'])?></td><td><?=!empty($x['active'])?'Visible':'Hidden'?></td><td class="actions"><a href="?edit=<?=(int)$x['id']?>">Edit</a><form method="post" data-confirm="Remove this social profile?"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$x['id']?>"><button>Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/../includes/admin_footer.php'; ?>